using Alba;
using Campaigns.Contracts;
using Campaigns.Slices.Campaigns;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: command. Status: ready.
///
/// The write side of this model exists to produce events for the five views. These tests keep it honest;
/// the suite this folder is actually about is ProjectionRecipeTests.
/// </summary>
public sealed class OpenCampaignTests(AppFixture fixture) : IntegrationContext(fixture)
{
    // a campaign can be opened
    //   GIVEN —
    //   WHEN  OpenCampaign
    //   THEN  CampaignOpened
    [Fact]
    public async Task ACampaignCanBeOpened()
    {
        var campaignId = SeedData.CampaignId;

        await WhenPosting(x =>
        {
            x.Post.Json(new OpenCampaign(campaignId, "January newsletter")).ToUrl(OpenCampaignEndpoint.Route);
            x.StatusCodeShouldBe(204);
        });

        var events = await EventsFor(campaignId);
        events.ShouldHaveSingleItem().ShouldBeOfType<CampaignOpened>()
            .Name.ShouldBe("January newsletter");
    }

    // a campaign with no name is refused
    //   GIVEN —
    //   WHEN  OpenCampaign
    //   THEN  error: NameRequired    (enforce="periphery")
    [Fact]
    public async Task ACampaignWithNoNameIsRefused()
    {
        var campaignId = Guid.NewGuid();

        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new OpenCampaign(campaignId, "")).ToUrl(OpenCampaignEndpoint.Route);
            x.StatusCodeShouldBe(400);
        });

        // A PERIPHERY failure has a different SHAPE from a decider's: the rule name lands in `errors`,
        // keyed by the property, rather than in `title`. Both put the rule name in the machine-readable
        // part, which is the contract — but a caller cannot read the two the same way.
        (await result.ReadAsTextAsync()).ShouldContain("NameRequired");

        // And the rule holds: nothing reached the stream.
        (await EventsFor(campaignId)).ShouldBeEmpty();
    }
}
